Function r <- Potencia(base As Integer, exponente As Integer)
  Define r As Integer;
  If exponente = 0 Then
    r <- 1;
  Else
    r <- base * Potencia(base, exponente - 1);
  EndIf
EndFunction

Algorithm Principal
  Define base, exponente As Integer;
  Read base;
  Read exponente;
  Write Potencia(base, exponente);
EndAlgorithm
